const js = String.raw`(()=>{const m=window.__WORKBENCH_MODEL__,app=document.querySelector('#app'),nav=document.querySelector('#nav');const views={acts:'Acts / scenes',puzzle:'Puzzle dependency',timeline:'State / inventory',objects:'Nine-verb desk',dialogue:'Dialogue tree',performance:'Performance score',evidence:'Nansen evidence',journeys:'Journey simulator',art:'Art capability',renderer:'Renderer risk',comments:'Comment book',concepts:'Review-only concepts'};let pendingAnchor=null,journeyState={},timelineIndex=0,performanceStep={},dialogueUsed={};const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const bookKey='trace-principal-review:'+m.revision;let book=JSON.parse(localStorage.getItem(bookKey)||'[]'),quarantine=null;const review=a=>'<div class="review-controls" data-review-anchor="'+esc(a)+'"><button data-comment="'+esc(a)+'">Add Comment</button><button data-approve="'+esc(a)+'">Approve</button></div>';const cards=(xs,fn)=>'<div class="grid">'+xs.map(fn).join('')+'</div>';const dl=x=>Object.entries(x).map(([k,v])=>'<dt>'+esc(k)+'</dt><dd>'+esc(Array.isArray(v)?v.join(', '):typeof v==='object'?JSON.stringify(v):v)+'</dd>').join('');const approval=a=>{const own=book.filter(x=>x.anchor===a);if(own.some(x=>['REVISE','CUT','DEFER'].includes(x.approval)))return 'UNRESOLVED';return own.some(x=>x.approval==='APPROVE'||x.approval==='APPROVE_WITH_NOTE')?'APPROVED':'UNREVIEWED'};function save(){localStorage.setItem(bookKey,JSON.stringify(book))}function addApproval(a){book.push({anchor:a,category:'KEEP',approval:'APPROVE',author:'Principal',timestamp:new Date().toISOString(),sourceRevision:m.revision,itemId:a,text:'Approved in Workbench.'});save();render()}for(const[k,label]of Object.entries(views)){const b=document.createElement('button');b.textContent=label;b.onclick=()=>{location.hash=k};nav.append(b)}function render(){const v=location.hash.slice(1)||'acts';if(v==='acts')acts();else if(v==='puzzle')puzzle();else if(v==='timeline')timeline();else if(v==='objects')objects();else if(v==='dialogue')dialogue();else if(v==='performance')performance();else if(v==='evidence')evidence();else if(v==='journeys')journeys();else if(v==='art')art();else if(v==='renderer')renderer();else if(v==='concepts')concepts();else comments();wire()}function wire(){app.querySelectorAll('[data-comment]').forEach(b=>b.onclick=()=>{pendingAnchor=b.dataset.comment;location.hash='comments'});app.querySelectorAll('[data-approve]').forEach(b=>b.onclick=()=>addApproval(b.dataset.approve))}function acts(){app.innerHTML='<h2>Act and scene navigator</h2>'+cards(m.acts,x=>{const a='act:'+x.id,children=m.reviewAnchors.filter(y=>y!==a&&(y.includes(x.id)||x.id==='ACT-1'&&y.startsWith('interaction:'))),unresolved=children.filter(y=>approval(y)==='UNRESOLVED').length;return '<article class="card '+(unresolved?'unresolved':'')+'"><h3>'+esc(x.id+' · '+x.label)+'</h3><dl>'+dl(x)+'</dl><p>Computed approval: <b>'+esc(unresolved?'UNRESOLVED_CHILDREN':approval(a))+'</b> · unresolved children '+unresolved+'</p>'+review(a)+'</article>'})}function puzzle(){app.innerHTML='<h2>Puzzle dependency</h2><p>Directed chain: '+m.puzzle.map(x=>esc(x.id)).join(' → ')+'</p>'+m.puzzle.map((x,i)=>'<article class="card"><p class="graph-edge">'+esc((i?m.puzzle[i-1].id:'START')+' → '+x.id+' → '+x.unlocks)+'</p><h3>'+esc(x.goal)+'</h3><dl>'+dl(x)+'</dl>'+review('puzzle:'+x.id)+'</article>').join('')}function timeline(){const x=m.timeline[timelineIndex];app.innerHTML='<h2>State and inventory timeline</h2><div class="controls"><button id="tback">Back</button><select id="tmile" aria-label="Direct milestone">'+m.timeline.map((y,i)=>'<option value="'+i+'" '+(i===timelineIndex?'selected':'')+'>'+esc(y.id)+'</option>').join('')+'</select><button id="tnext">Forward</button></div><article class="card"><h3>'+esc(x.id)+'</h3><dl>'+dl(x)+'</dl>'+review('timeline:'+x.id)+'</article>';app.querySelector('#tback').onclick=()=>{timelineIndex=Math.max(0,timelineIndex-1);timeline();wire()};app.querySelector('#tnext').onclick=()=>{timelineIndex=Math.min(m.timeline.length-1,timelineIndex+1);timeline();wire()};app.querySelector('#tmile').onchange=e=>{timelineIndex=+e.target.value;timeline();wire()}}function objects(){app.innerHTML='<h2>Nine-verb desk</h2><p>'+m.interactions.length+' cells · exact literal responses and review metadata.</p>'+cards(m.interactions,x=>'<article class="card"><h3>'+esc(x.hotspot+' · '+x.verb)+'</h3><p>'+x.exactResponses.map(l=>'<b>'+esc(l.speaker)+':</b> '+esc(l.text)).join('<br>')+'</p><dl>'+dl({repeat:x.repeat_behavior,progression:x.progressionEffect,reaction:x.characterReaction,cues:x.performanceCues,sound:x.soundCaption,artNeed:x.artNeed})+'</dl>'+review(x.anchor)+'</article>')}function dialogue(){const menus=m.dialogues.menus.map(menu=>{const used=dialogueUsed[menu.id]||[];const choices=menu.choices.filter(c=>c.persistent||!used.includes(c.id));return '<article class="card"><h3>'+esc(menu.id+' · '+menu.context)+'</h3><p>Available topics disappear after use; help/exit persist.</p>'+choices.map(c=>'<section><button data-choice="'+esc(menu.id+':'+c.id)+'">'+esc(c.label)+'</button><small> '+esc(c.completion+' · '+(c.semantic_action||'transcript only'))+'</small>'+review('dialogue-choice:'+menu.id+':'+c.id)+'</section>').join('')+'<button data-reset-menu="'+esc(menu.id)+'">Reset menu</button>'+review('dialogue-menu:'+menu.id)+'</article>'}).join('');app.innerHTML='<h2>Dialogue-tree reader</h2><h3>Exact sequences</h3>'+cards(m.dialogues.sequences,x=>'<article class="card"><h3>'+esc(x.id)+'</h3><dl>'+dl({prerequisite:x.prerequisite,channel:x.channel,oneShot:x.oneShot,repeat:x.repeatRule,effect:x.downstreamEffect,order:x.transcriptOrder})+'</dl><ol>'+x.lines.map(l=>'<li><b>'+esc(l.speaker)+':</b> '+esc(l.text)+' <small>'+esc(l.key)+'</small></li>').join('')+'</ol>'+review('dialogue:'+x.id)+'</article>')+'<h3>Selectable topics</h3><div class="grid">'+menus+'</div>';app.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{const[id,choice]=b.dataset.choice.split(':');const menu=m.dialogues.menus.find(x=>x.id===id),item=menu.choices.find(x=>x.id===choice);if(!item.persistent){dialogueUsed[id]=[...(dialogueUsed[id]||[]),choice]}b.insertAdjacentHTML('afterend','<p>'+item.replies.map(l=>'<b>'+esc(l.speaker)+':</b> '+esc(l.text)).join('<br>')+'</p>');if(!item.persistent)b.disabled=true});app.querySelectorAll('[data-reset-menu]').forEach(b=>b.onclick=()=>{dialogueUsed[b.dataset.resetMenu]=[];dialogue();wire()})}function performance(){app.innerHTML='<h2>Phrase-level performance score</h2><p>Six parallel tracks. Preview notes are visual metadata and are never announced as dialogue.</p>'+cards(m.performance,x=>{const same=m.performance.filter(y=>y.copyKey===x.copyKey),step=performanceStep[x.copyKey]||0,active=same.slice(0,step+1);return '<article class="card"><h3>'+esc(x.id)+'</h3><p>'+esc(x.text)+'</p><div class="tracks">'+['FACE','GAZE','BODY','PROP','VOICE_TEXT','TIME'].map(t=>'<div class="track"><b>'+t+'</b><br>'+esc(active.filter(y=>y.track===t).at(-1)?.intention||'—')+'</div>').join('')+'</div><div class="preview" data-static="true"><span aria-hidden="true">GENERIC '+esc(x.actor)+' · '+esc(x.trigger+(x.anchor?' @ '+x.anchor:''))+'</span></div><button data-perf-prev="'+esc(x.copyKey)+'">Previous cue</button><button data-perf-next="'+esc(x.copyKey)+'">Next cue</button><label><input type="checkbox" data-perf-reduced> Reduced Motion static preview</label>'+review('performance:'+x.id)+'</article>'}) ;app.querySelectorAll('[data-perf-prev]').forEach(b=>b.onclick=()=>{const k=b.dataset.perfPrev;performanceStep[k]=Math.max(0,(performanceStep[k]||0)-1);performance();wire()});app.querySelectorAll('[data-perf-next]').forEach(b=>b.onclick=()=>{const k=b.dataset.perfNext;performanceStep[k]=Math.min(m.performance.filter(x=>x.copyKey===k).length-1,(performanceStep[k]||0)+1);performance();wire()});app.querySelectorAll('[data-perf-reduced]').forEach(c=>c.onchange=()=>{c.closest('.card').querySelector('.preview').dataset.reduced=String(c.checked)})}function evidence(){app.innerHTML='<h2>Nansen evidence and claim view</h2><p><b>'+esc(m.evidence.auditStatus)+'</b> · 25 semantic views; seven bounded no-match views are explicitly separated below. Exact Hero proof remains separate.</p><h3>All 25 semantic views</h3>'+cards(m.evidence.records,x=>'<article class="card"><h3>'+esc(x.id)+'</h3><dl>'+dl(x)+'</dl>'+review('evidence:'+x.id)+'</article>')+'<h3>Seven bounded no-match controls</h3>'+cards(m.evidence.boundedNoMatch,x=>'<article class="card"><h3>'+esc(x.id+' · '+x.zeroResultClass)+'</h3><p>'+esc(x.question)+'</p><p>Cannot establish: '+esc(x.cannotEstablish.join('; '))+'</p>'+review('evidence:'+x.id)+'</article>')}function journeys(){app.innerHTML='<h2>Journey simulator</h2><p>Conceptual only; real game save is never read or modified.</p>'+cards(m.journeys,j=>{const i=journeyState[j.id]||0,x=j.steps[i];return '<article class="card"><h3>'+esc(j.label)+'</h3><p>Step '+(i+1)+' / '+j.steps.length+' · '+esc(x.name)+'</p><dl>'+dl(x)+'</dl><button data-jback="'+j.id+'">Back</button><button data-jnext="'+j.id+'">Step</button><button data-jreset="'+j.id+'">Reset</button><button data-jbranch="'+j.id+'">Inspect branch</button>'+review('journey:'+j.id)+'</article>'});app.querySelectorAll('[data-jback]').forEach(b=>b.onclick=()=>{journeyState[b.dataset.jback]=Math.max(0,(journeyState[b.dataset.jback]||0)-1);journeys();wire()});app.querySelectorAll('[data-jnext]').forEach(b=>b.onclick=()=>{const j=m.journeys.find(x=>x.id===b.dataset.jnext);journeyState[j.id]=Math.min(j.steps.length-1,(journeyState[j.id]||0)+1);journeys();wire()});app.querySelectorAll('[data-jreset]').forEach(b=>b.onclick=()=>{journeyState[b.dataset.jreset]=0;journeys();wire()});app.querySelectorAll('[data-jbranch]').forEach(b=>b.onclick=()=>{const j=m.journeys.find(x=>x.id===b.dataset.jbranch),x=j.steps[journeyState[j.id]||0];alert('Available branches: '+x.availableChoices.join(' | '))})}function art(){app.innerHTML='<h2>Art capability</h2>'+cards(m.artIntentions,x=>'<article class="card"><h3>'+esc(x.intention)+'</h3><dl>'+dl(x)+'</dl>'+review('art:'+x.intention)+'</article>')}function renderer(){app.innerHTML='<h2>Actual thirteen-line game-renderer review</h2><p>The embedded surface is a separate review build that imports the same GameDialoguePresentation component used by ordinary game speech. Review full-screen CRT, docked overlay, plain list, Reduced Motion, and browser zoom there.</p><p><a href="actual-renderer/index.html" target="_blank">Open actual renderer in a new tab</a></p><iframe class="renderer-frame" title="Actual game renderer" src="actual-renderer/index.html"></iframe><h3>Thirteen immutable lines</h3>'+cards(m.rendererRisk,x=>'<article class="card"><h3>'+esc(x.key)+'</h3><p>'+esc(x.text)+'</p>'+review('renderer:'+x.key)+'</article>')}function concepts(){app.innerHTML='<h2>Review-only concepts</h2><p>None enters runtime, inventory, catalog, proof, or the normal build.</p>'+cards(m.concepts,x=>'<article class="card review-only"><h3>'+esc(x.id+' · '+x.title)+'</h3><dl>'+dl(x)+'</dl><span class="badge">NOT IN RUNTIME</span>'+review('concept:'+x.id)+'</article>')}function comments(){const options=xs=>xs.map(x=>'<option>'+esc(x)+'</option>').join('');const active=pendingAnchor||m.reviewAnchors[0];app.innerHTML='<h2>Principal comment book</h2><p>Revision <code>'+esc(m.revision)+'</code></p><p id="import-status" class="status '+(quarantine?'quarantine':'')+'">'+esc(quarantine||'Ready. Imports must match schema, revision, and source identity.')+'</p><label>Stable anchor<select id="anchor">'+m.reviewAnchors.map(x=>'<option '+(x===active?'selected':'')+'>'+esc(x)+'</option>').join('')+'</select></label><label>Category<select id="category">'+options(m.commentContract.categories)+'</select></label><label>Approval<select id="approval">'+options(m.commentContract.states)+'</select></label><label>Author<input id="author" value="Principal"></label><label>Comment<textarea id="text"></textarea></label><button id="save">Save locally</button><button id="json">Export JSON</button><button id="md">Export Markdown</button><label>Import review book<input id="import" type="file" accept="application/json,text/markdown,.md"></label><section id="book"></section>';pendingAnchor=null;const draw=()=>app.querySelector('#book').innerHTML=cards(book,x=>'<article class="card '+(['REVISE','CUT','DEFER'].includes(x.approval)?'unresolved':'')+'"><h3>'+esc(x.anchor+' · '+x.category)+'</h3><p>'+esc(x.text)+'</p><small>'+esc(x.author+' · '+x.timestamp+' · '+x.approval+' · '+x.sourceRevision)+'</small></article>');const payload=()=>({schemaVersion:'2.0.0',revision:m.revision,sourceIdentity:m.sourceIdentity,comments:book});const download=(name,text,type)=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),0)};app.querySelector('#save').onclick=()=>{book.push({anchor:app.querySelector('#anchor').value,category:app.querySelector('#category').value,approval:app.querySelector('#approval').value,author:app.querySelector('#author').value,timestamp:new Date().toISOString(),sourceRevision:m.revision,itemId:app.querySelector('#anchor').value,text:app.querySelector('#text').value});save();draw()};app.querySelector('#json').onclick=()=>download('PRINCIPAL_REVIEW_BOOK.json',JSON.stringify(payload(),null,2),'application/json');app.querySelector('#md').onclick=()=>{const p=payload();download('PRINCIPAL_REVIEW_BOOK.md','# Principal Review Book\n\nRevision: '+m.revision+'\n\n'+book.map(x=>'## '+x.anchor+' — '+x.category+'\n\n'+x.text+'\n\n- '+x.approval+' · '+x.author+' · '+x.timestamp+'\n').join('\n')+'\n<!-- REVIEW_BOOK_JSON '+btoa(unescape(encodeURIComponent(JSON.stringify(p))))+' -->\n','text/markdown')};app.querySelector('#import').onchange=async e=>{try{const f=e.target.files[0],text=await f.text();let value;if(f.name.endsWith('.md')){const match=text.match(/<!-- REVIEW_BOOK_JSON ([A-Za-z0-9+/=]+) -->/);if(!match)throw Error('MARKDOWN_EMBEDDED_JSON_MISSING');value=JSON.parse(decodeURIComponent(escape(atob(match[1]))))}else value=JSON.parse(text);const mismatch=[];if(value.schemaVersion!=='2.0.0')mismatch.push('schema');if(value.revision!==m.revision)mismatch.push('revision');if(JSON.stringify(value.sourceIdentity)!==JSON.stringify(m.sourceIdentity))mismatch.push('source identity');if(!Array.isArray(value.comments))mismatch.push('comments');if(mismatch.length){quarantine='QUARANTINED — mismatched '+mismatch.join(', ')+'; current review book was not replaced.';comments();wire();return}book=value.comments;save();quarantine='IMPORT ACCEPTED — schema, revision, and source identity match.';comments();wire()}catch(error){quarantine='QUARANTINED — '+error.message+'; current review book was not replaced.';comments();wire()}};draw()}addEventListener('hashchange',render);render()})();`

